def _r(ex, base, step=0, weeks=None):
    item = {"ex": ex, "reps": base, "step": step}
    return {**item, "weeks": weeks} if weeks else item


def _s(ex, base, step=0, weeks=None):
    item = {"ex": ex, "seconds": base, "step": step}
    return {**item, "weeks": weeks} if weeks else item


